cat > src/server/repositories/api-token-repository.ts <<'EOF'
/**
 * Personal API token rows. Every read is filtered by `orgId`; the secret never reaches this layer, only its hash.
 *
 * Must call (do not reimplement): orgPredicate, toApiToken
 */
import { and, count, desc, eq, gt, isNull, or } from "drizzle-orm";
import { apiTokens, getDb } from "@/server/db";
import type { NewApiTokenRow } from "@/server/db";
import type { ApiToken } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";

export async function insertApiToken(row: NewApiTokenRow): Promise<ApiToken> {
  const inserted = getDb()
    .insert(apiTokens)
    .values(row)
    .returning()
    .get();
  return toApiToken(inserted);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Hash lookup for authentication. Deliberately unscoped: the org comes from the row. */
export async function findApiTokenRowByHash(
  tokenHash: string,
): Promise<ApiToken & { readonly tokenHash: string } | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? { ...toApiToken(row), tokenHash: row.tokenHash } : null;
}

/** Every token a user owns in one org, revoked and expired included, newest first. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();
  return rows.map(toApiToken);
}

/** Tokens a user holds that are neither revoked nor expired at `now`. */
export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Live (not yet revoked) tokens a user holds in one org, expired ones included. */
export async function listUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
