/**
 * Personal API tokens: creation, listing, revocation and bearer authentication.
 *
 * Only a SHA-256 digest of each secret is stored. Revocation also happens
 * implicitly when a member is removed from an organization.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, newId
 */
import { newId } from "@/lib/id";
import { hashToken, randomToken } from "@/lib/hash";
import { emit, subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { createApiTokenSchema } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const SECRET_PREFIX = "tfk_";
/** Characters of the secret shown as the token's visible prefix. */
const DISPLAY_PREFIX_LENGTH = 12;
const MAX_USABLE_TOKENS_PER_USER = 5;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Creates a token for the actor. The returned `token` is the only copy of the
 * secret; it is never stored or logged.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "api_token:write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);

  const usable = await apiTokenRepo.countUsableApiTokens(
    parsed.orgId,
    actor.userId,
    createdAt,
  );
  if (usable >= MAX_USABLE_TOKENS_PER_USER) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS_PER_USER} active API tokens in this organization`,
    );
  }

  const token = `${SECRET_PREFIX}${randomToken(32)}`;
  const tokenId = newId();

  const apiToken = await apiTokenRepo.insertApiToken({
    id: tokenId,
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(
      new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
    ),
    lastUsedAt: null,
    revokedAt: null,
    createdAt,
    updatedAt: createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    tokenUserId: apiToken.userId,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/** Tokens of `userId` (default: the actor) in `orgId`, revoked and expired included. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  const target = userId ?? actor.userId;
  if (target !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokensForUser(orgId, target);
}

/**
 * Revokes one token. Revoking an already-revoked token returns it unchanged
 * and records nothing.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const token = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (token.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  if (token.revokedAt !== null) return token;

  return markRevoked(actorEnvelope(actor), token);
}

/**
 * Resolves a bearer secret to the `Actor` it acts as, or `null` when the token
 * is unknown, revoked, expired, or its user/org is no longer usable. A
 * successful call stamps `lastUsedAt`.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  const row = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (row === null) return null;

  const now = new Date();
  if (row.revokedAt !== null) return null;
  if (Date.parse(row.expiresAt) <= now.getTime()) return null;

  const org = await orgRepo.findOrgById(row.orgId);
  if (org === null || isArchived(org)) return null;

  const member = await memberRepo.findMember(row.orgId, row.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.setApiTokenLastUsedAt(row.id, toIsoTimestamp(now));

  return {
    userId: row.userId,
    orgId: row.orgId,
    role: row.scope === "read" ? "viewer" : member.role,
  };
}

/** Sets `revokedAt`, then publishes the audit-worthy fact. */
async function markRevoked(
  origin: EventEnvelope,
  token: ApiToken,
): Promise<ApiToken> {
  const revoked = requireFound(
    await apiTokenRepo.setApiTokenRevokedAt(
      token.orgId,
      token.id,
      toIsoTimestamp(new Date()),
    ),
    "ApiToken",
    token.id,
  );

  await emit("api_token.revoked", {
    ...origin,
    tokenId: revoked.id,
    tokenUserId: revoked.userId,
  });

  return revoked;
}

/**
 * Revokes every live token of a removed member in that organization, audited
 * with the remover as actor. Other organizations are untouched.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedApiTokensForUser(
      payload.orgId,
      payload.userId,
    );

    for (const token of tokens) {
      await markRevoked(envelope(payload.orgId, payload.actorId), token);
    }
  });
}
